// services/offlineQueue.ts
import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';

export interface QueuedMessage {
  id: string; // ID temporaire
  chatId: string;
  content: string;
  type: 'text' | 'image';
  imageUri?: string;
  timestamp: number;
  retries: number;
  status: 'pending' | 'sending' | 'failed';
}

class OfflineQueueService {
  private readonly QUEUE_KEY = '@offline_messages';
  private isProcessing = false;
  private isOnline = false;

  constructor() {
    this.init();
  }

  private async init() {
    // Vérifier la connexion initiale
    const state = await NetInfo.fetch();
    this.isOnline = state.isConnected ?? false;

    // Écouter les changements de connexion
    NetInfo.addEventListener((state) => {
      const wasOffline = !this.isOnline;
      this.isOnline = state.isConnected ?? false;

      // Si la connexion est rétablie, vider la file d'attente
      if (wasOffline && this.isOnline) {
        this.processQueue();
      }
    });
  }

  // Ajouter un message à la file d'attente
  async addMessage(message: Omit<QueuedMessage, 'id' | 'status' | 'retries'>): Promise<string> {
    const id = `temp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const queuedMessage: QueuedMessage = {
      ...message,
      id,
      status: 'pending',
      retries: 0,
    };

    // Stocker dans AsyncStorage
    await this.saveToQueue(queuedMessage);

    // Si connecté, tenter l'envoi immédiat
    if (this.isOnline) {
      this.processQueue();
    }

    return id;
  }

  // Sauvegarder dans AsyncStorage
  private async saveToQueue(message: QueuedMessage) {
    try {
      const queue = await this.getQueue();
      queue.push(message);
      await AsyncStorage.setItem(this.QUEUE_KEY, JSON.stringify(queue));
    } catch (error) {
      console.error('Erreur lors de la sauvegarde du message', error);
    }
  }

  // Récupérer la file d'attente
  private async getQueue(): Promise<QueuedMessage[]> {
    try {
      const data = await AsyncStorage.getItem(this.QUEUE_KEY);
      return data ? JSON.parse(data) : [];
    } catch {
      return [];
    }
  }

  // Vider la file d'attente
  private async clearQueue() {
    await AsyncStorage.removeItem(this.QUEUE_KEY);
  }

  // Supprimer un message spécifique de la file
  private async removeFromQueue(messageId: string) {
    const queue = await this.getQueue();
    const updatedQueue = queue.filter(msg => msg.id !== messageId);
    await AsyncStorage.setItem(this.QUEUE_KEY, JSON.stringify(updatedQueue));
  }

  // Traiter la file d'attente
  async processQueue() {
    if (this.isProcessing || !this.isOnline) {
      return;
    }

    this.isProcessing = true;
    const queue = await this.getQueue();
    const failedMessages: QueuedMessage[] = [];

    for (const message of queue) {
      if (message.status === 'sending') continue;

      try {
        // Marquer comme en cours d'envoi
        message.status = 'sending';
        await this.updateMessageInQueue(message);

        // Envoyer le message via WebSocket ou API
        const response = await this.sendMessageToServer(message);

        // Supprimer de la file si réussi
        await this.removeFromQueue(message.id);

        // Émettre un événement pour mettre à jour l'UI
        this.onMessageSent(message.id, response);

      } catch (error) {
        // En cas d'échec, incrémenter le compteur de retries
        message.retries += 1;
        message.status = message.retries >= 3 ? 'failed' : 'pending';
        await this.updateMessageInQueue(message);

        if (message.status === 'failed') {
          failedMessages.push(message);
        }
      }
    }

    this.isProcessing = false;

    // Notifier des échecs
    if (failedMessages.length > 0) {
      this.onMessagesFailed(failedMessages);
    }
  }

  // Mettre à jour un message dans la file
  private async updateMessageInQueue(message: QueuedMessage) {
    const queue = await this.getQueue();
    const index = queue.findIndex(msg => msg.id === message.id);
    if (index !== -1) {
      queue[index] = message;
      await AsyncStorage.setItem(this.QUEUE_KEY, JSON.stringify(queue));
    }
  }

  // Envoyer le message au serveur
  private async sendMessageToServer(message: QueuedMessage): Promise<any> {
    // Implémentation selon l'API
    return await chatService.sendMessage(message.chatId, {
      content: message.content,
      type: message.type,
      imageUri: message.imageUri,
    });
  }

  // Callback de succès
  private onMessageSent(tempId: string, response: any) {
    // Émettre un événement via le store ou EventEmitter
    chatStore.updateMessage(tempId, {
      id: response.id,
      status: 'sent',
    });
  }

  // Callback d'échec
  private onMessagesFailed(messages: QueuedMessage[]) {
    // Afficher une notification à l'utilisateur
    notificationStore.showToast(
      `${messages.length} message(s) non envoyé(s)`, 
      'error'
    );

    // Mettre à jour le store
    messages.forEach(msg => {
      chatStore.updateMessage(msg.id, { status: 'failed' });
    });
  }

  // Réessayer un message échoué
  async retryMessage(messageId: string) {
    const queue = await this.getQueue();
    const message = queue.find(msg => msg.id === messageId);
    if (message && message.status === 'failed') {
      message.retries = 0;
      message.status = 'pending';
      await this.updateMessageInQueue(message);
      this.processQueue();
    }
  }
}

export const offlineQueue = new OfflineQueueService();
```

