const RETRY_CONFIG = {
  maxRetries: 3,
  baseDelay: 1000, // 1 seconde
  maxDelay: 30000, // 30 secondes
  timeout: 10000, // 10 secondes
  retryableStatuses: [408, 429, 500, 502, 503, 504],
  retryableErrors: [
    'ECONNABORTED',
    'ECONNRESET',
    'ENETUNREACH',
    'ETIMEDOUT',
    'ERR_NETWORK',
  ],
};

const api = axios.create({
  baseURL: API_URL,
  timeout: RETRY_CONFIG.timeout,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Interceptor pour le token JWT
api.interceptors.request.use(
  (config) => {
    const token = authStore.getState().token;
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Interceptor pour le retry
api.interceptors.response.use(
  (response) => response,
  async (error: AxiosError) => {
    const config = error.config as AxiosRequestConfig & { _retry?: number };

    // Ne pas retenter si on a déjà retenté ou si on est en mode upload
    if (!config || config._retry === undefined) {
      config._retry = 0;
    }

    // Vérifier si l'erreur est retryable
    const isRetryableStatus = error.response && 
      RETRY_CONFIG.retryableStatuses.includes(error.response.status);

    const isRetryableError = error.code && 
      RETRY_CONFIG.retryableErrors.includes(error.code);

    const shouldRetry = (isRetryableStatus || isRetryableError) 
      && config._retry < RETRY_CONFIG.maxRetries;

    if (shouldRetry) {
      config._retry++;

      // Calcul du délai avec backoff exponentiel
      const delay = Math.min(
        RETRY_CONFIG.baseDelay * Math.pow(2, config._retry - 1) * 
        (0.5 + Math.random() * 0.5), // Ajout d'un jitter pour éviter la tempête de retry
        RETRY_CONFIG.maxDelay
      );

      // Afficher une notification
      const isOffline = error.code === 'ERR_NETWORK' || error.code === 'ENETUNREACH';
      if (isOffline) {
        // Ajouter à la file d'attente hors ligne
        await offlineQueue.addToQueue({
          id: `retry_${Date.now()}`,
          type: 'api_request',
          config: config,
          timestamp: Date.now(),
        });
        return Promise.reject(error);
      }

      // Afficher un message de tentative
